def semver_sort(versions):
    def parse_version(version):
        # Split build metadata
        if '+' in version:
            main, build = version.split('+', 1)
        else:
            main = version

        # Split pre-release
        if '-' in main:
            version_part, prerelease = main.split('-', 1)
        else:
            version_part = main
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = version_part.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        # Parse pre-release identifiers
        if prerelease is not None:
            prerelease_ids = prerelease.split('.')
        else:
            prerelease_ids = None

        return (major, minor, patch, prerelease_ids)

    def prerelease_key(prerelease_ids):
        if prerelease_ids is None:
            # Version without pre-release comes after version with pre-release
            return (1,)

        # Convert each identifier to a comparable form
        keys = []
        for identifier in prerelease_ids:
            if identifier.isdigit():
                # All-digit identifiers: (0, numeric_value)
                keys.append((0, int(identifier)))
            else:
                # Other identifiers: (1, string_value)
                keys.append((1, identifier))

        # Return tuple where fewer identifiers sort first
        return (0, tuple(keys))

    def sort_key(version):
        major, minor, patch, prerelease_ids = parse_version(version)
        return (major, minor, patch, prerelease_key(prerelease_ids))

    # Sort using stable sort to preserve input order for equal precedence
    return sorted(versions, key=sort_key)

